INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(5383, 'plPL', 'Torba okropności Krastinova', 'Otwierasz torbę i znajdujesz w niej rozmaite narzędzia tortur. Pośród tych akcesoriów twoją uwagę przykuwa dziwny przedmiot: fiolka krwi – wciąż ciepła w dotyku.$B$BSądzisz, że twoje odkrycie może zainteresować Sarkhoffów.', 'Zanieś Torbę okropności Evie Sarkhoff w Caer Darrow.', '', '', '', '', '', '', 0);
