INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(1898, 'plPL', 'Strom pozostał centralnym ośrodkiem Aratoru, lecz podobnie jak Dalaran, na kontynencie Lordaeronu powstało wiele nowych miast-państw. Pierwszymi z nich były Gilneas, Alterak i Kul Tiras. Choć każde miało własne obyczaje i sposoby prowadzenia handlu, wszystkie uznawały jednoczącą władzę Stromu. ', 0),
(1899, 'plPL', 'Pod czujnym okiem Zakonu Tirisfal Dalaran stał się głównym ośrodkiem nauki dla magów z całej krainy. Rządzący Dalaranem magokraci założyli Kirin Tor – wyspecjalizowane bractwo, któremu powierzono katalogowanie i badanie każdego zaklęcia, artefaktu i magicznego przedmiotu znanego wówczas ludzkości. ', 0),
(1900, 'plPL', 'Gilneas i Alterak stały się gorliwymi stronnikami Stromu i wystawiły potężne armie, które badały górzyste południowe ziemie Khaz Modan. To właśnie wtedy ludzie po raz pierwszy spotkali starożytną rasę krasnoludów i odwiedzili ich jaskiniowe, podziemne miasto – Żelazną Kuźnię. Ludzie i krasnoludy podzielili się wieloma tajnikami kowalstwa i inżynierii i odkryli wspólne umiłowanie walki oraz opowieści.', 0),
(1901, 'plPL', 'Miasto-państwo Kul Tiras, założone na dużej wyspie na południe od Lordaeronu, rozwinęło kwitnącą gospodarkę opartą na rybołówstwie i żegludze. Z czasem Kul Tiras zbudowało potężną flotę statków handlowych, które przemierzały wszystkie znane ziemie w poszukiwaniu egzotycznych towarów na wymianę i sprzedaż. Jednak nawet gdy gospodarka Aratoru rozkwitała, jego najsilniejsze filary zaczęły się rozpadać.', 0),
(1902, 'plPL', 'Z czasem lordowie Stromu zapragnęli przenieść swoje posiadłości na bujne północne ziemie Lordaeronu i opuścić suche krainy południa. Dziedzice króla Thoradina, ostatni potomkowie rodu Arathi, twierdzili, że Stromu nie wolno porzucać, czym ściągnęli na siebie niezadowolenie większości obywateli, którzy również pragnęli odejść. ', 0),
(1903, 'plPL', 'Lordowie Stromu, szukając czystości i oświecenia na dzikiej północy, postanowili porzucić swoje starożytne miasto. Daleko na północ od Dalaranu zbudowali nowe miasto-państwo, które nazwali Lordaeronem. Od tego miasta-państwa nazwę wziął cały kontynent. Lordaeron stał się mekką dla pielgrzymów i wszystkich, którzy szukali wewnętrznego spokoju i bezpieczeństwa. ', 0),
(1904, 'plPL', 'Potomkowie rodu Arathi, pozostawieni w kruszących się murach starożytnego Stromu, postanowili wyruszyć na południe, za skaliste góry Khaz Modan. Ich wędrówka zakończyła się po wielu długich porach roku, a oni osiedlili się w północnej części kontynentu, który nazwali Azeroth. W żyznej dolinie założyli królestwo Wichrogrodu, które szybko stało się samowystarczalną potęgą. ', 0),
(1905, 'plPL', 'Nieliczni wojownicy, którzy zostali w Stromie, postanowili pozostać i strzec starożytnych murów swojego miasta. Strom nie był już sercem imperium, ale przekształcił się w nowy naród, znany jako Stromgard. Choć każde z miast-państw na swój sposób prosperowało, imperium Aratoru w praktyce się rozpadło. W miarę jak każdy naród wykształcał własne obyczaje i wierzenia, coraz bardziej oddzielały się od siebie. Wizja zjednoczonej ludzkości króla Thoradina w końcu przeminęła.', 0),
(1992, 'plPL', 'Gdy ognie Drugiej Wojny przygasły, Przymierze podjęło zdecydowane kroki, by powstrzymać zagrożenie ze strony orków. W południowym Lordaeronie zbudowano kilka dużych obozów internowania dla pojmanych orków. Strzeżone zarówno przez paladynów, jak i przez weteranów Przymierza, obozy okazały się wielkim sukcesem.', 0),
(1993, 'plPL', 'Choć pojmane orki były spięte i spragnione ponownej walki, komendanci obozów, stacjonujący w starej twierdzy-więzieniu Durnhold, utrzymywali spokój i solidne pozory porządku.', 0),
(1994, 'plPL', 'Tymczasem na piekielnym świecie Draenoru nowa armia orków szykowała się do uderzenia na niczego niespodziewające się Przymierze. Ner\'zhul, dawny mentor Gul\'dana, zgromadził pozostałe klany orków pod swoim mrocznym sztandarem. Wspierany przez klan Cienistego Księżyca, stary szaman planował otworzyć na Draenorze kilka portali, które poprowadziłyby Hordę do nowych, nieskażonych światów.', 0),
(1995, 'plPL', 'Aby zasilić nowe portale, potrzebował kilku zaklętych artefaktów z Azeroth. By je zdobyć, Ner\'zhul ponownie otworzył Mroczny Portal i posłał przez niego swoje wygłodniałe sługi.', 0),
(1996, 'plPL', 'Nowa Horda, prowadzona przez doświadczonych wodzów, takich jak Grom Piekłorycz i Kilrogg Martwooki (z klanu Krwawiącego Oczodołu),\n zaskoczyła siły obronne Przymierza i spustoszyła okolicę. Pod precyzyjnym dowództwem Ner\'zhula orkowie szybko zebrali potrzebne artefakty i uciekli z powrotem w bezpieczne progi Draenoru.', 0),
(1997, 'plPL', 'Król Lordaeronu Terenas, przekonany, że orkowie szykują nową inwazję na Azeroth, zebrał swoich najbardziej zaufanych dowódców. Rozkazał generałowi Turalyonowi i arcymagowi Khadgarowi poprowadzić wyprawę przez Mroczny Portal, by raz na zawsze położyć kres zagrożeniu ze strony orków. Siły Turalyona i Khadgara wkroczyły na Draenor i raz po raz ścierały się z klanami Ner\'zhula na spustoszonym Półwyspie Piekielnego Ognia.', 0),
(1998, 'plPL', 'Nawet z pomocą wysokiej elfki Allerii Bieżywiatr, krasnoluda Kurdrana Dzikiego Młota i doświadczonego żołnierza Danatha Trollbane\'a Khadgar nie zdołał powstrzymać Ner\'zhula przed otwarciem portali do innych światów.', 0),
(1999, 'plPL', 'Ner\'zhul w końcu otworzył portale do innych światów, lecz nie przewidział, jak straszliwą cenę przyjdzie mu zapłacić. Ogromne energie portali zaczęły rozdzierać samą tkankę Draenoru. Gdy siły Turalyona rozpaczliwie walczyły o powrót do Azeroth, świat Draenoru zaczął zapadać się w sobie. Grom Piekłorycz i Kilrogg Martwooki, zdając sobie sprawę, że szalone plany Ner\'zhula skażą na zagładę całą ich rasę, zebrali pozostałych orków i uciekli z powrotem do względnie bezpiecznego Azeroth.', 0),
(2000, 'plPL', 'Na Draenorze Turalyon i Khadgar zgodzili się na najwyższe poświęcenie – zniszczenie Mrocznego Portalu od swojej strony. Choć miało to kosztować życie ich samych i ich towarzyszy, wiedzieli, że to jedyny sposób, by zapewnić Azeroth przetrwanie. Gdy Piekłorycz i Martwooki przedzierali się przez szeregi ludzi w rozpaczliwej próbie odzyskania wolności, Mroczny Portal eksplodował za ich plecami. Dla nich i dla pozostałych w Azeroth orków nie było już powrotu.', 0),
(2001, 'plPL', 'Ner\'zhul i wierny mu klan Cienistego Księżyca przeszli przez największy z nowo utworzonych portali, gdy potężne erupcje wulkanów zaczęły rozrywać kontynenty Draenoru. Płonące morza wezbrały i zalały strzaskany krajobraz, aż w końcu udręczony świat pochłonęła potężna, apokaliptyczna eksplozja.', 0),
(2101, 'plPL', 'Choć był osłabiony, Arthas ostatecznie wymanewrował Illidana i jako pierwszy dotarł do Mroźnego Tronu. Swoim runicznym ostrzem, Ostrzem Mrozu, Arthas roztrzaskał lodowe więzienie Króla Lisza i uwolnił w ten sposób zaklęty hełm i napierśnik Ner\'zhula.', 0),
(2102, 'plPL', 'Arthas włożył na głowę ten niewyobrażalnie potężny hełm i stał się nowym Królem Liszem. Duchy Ner\'zhula i Arthasa stopiły się w jedną potężną istotę – dokładnie tak, jak zawsze planował Ner\'zhul. Illidan i jego oddziały musieli w niesławie uciekać z powrotem na Rubież, a Arthas stał się jedną z najpotężniejszych istot, jakie kiedykolwiek znał świat.', 0),
(2103, 'plPL', 'Obecnie Arthas, nowy i nieśmiertelny Król Lisz, przebywa w Północnej Grani; podobno odbudowuje cytadelę Lodowej Korony. Jego zaufany zastępca, Kel\'Thuzad, dowodzi Plagą na Plagowiskach. Sylwana i jej zbuntowani Porzuceni utrzymują jedynie Polany Tirisfal, niewielką część wyniszczonego wojną królestwa.', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(5950, 'plPL', 'Oto przykład tego, czego nie należy przyzywać. Spójrzcie, jest wątły i kruchy. Jedno porządne uderzenie buławą i odłamki kości rozlecą się na wszystkie strony.', 'Oto przykład tego, czego nie należy przyzywać. Spójrzcie, jest wątły i kruchy. Jedno porządne uderzenie buławą i odłamki kości rozlecą się na wszystkie strony.', 0),
(5951, 'plPL', 'Zwróćcie uwagę na słabą strukturę więzi tego egzemplarza. Pamiętajcie, by dokończyć inkantacje, bo inaczej skończycie z czymś takim.', 'Zwróćcie uwagę na słabą strukturę więzi tego egzemplarza. Pamiętajcie, by dokończyć inkantacje, bo inaczej skończycie z czymś takim.', 0),
(5952, 'plPL', 'Ten jest nieco lepszy od poprzedniego. Wciąż jednak cierpi na tę samą wątłą budowę kości co pozostałe. Jeśli przyzwiecie coś takiego, jesteście na dobrej drodze.', 'Ten jest nieco lepszy od poprzedniego. Wciąż jednak cierpi na tę samą wątłą budowę kości co pozostałe. Jeśli przyzwiecie coś takiego, jesteście na dobrej drodze.', 0),
(5953, 'plPL', 'Ojej, ten jest po prostu do niczego. Spróbuję jeszcze raz.', 'Ojej, ten jest po prostu do niczego. Spróbuję jeszcze raz.', 0),
(5954, 'plPL', 'Hmm, ten wygląda, jakby lepiej się nadawał na dzwonki wietrzne. Notujcie, klaso... Czegoś takiego NIE chcecie przyzwać w ogniu walki.', 'Hmm, ten wygląda, jakby lepiej się nadawał na dzwonki wietrzne. Notujcie, klaso... Czegoś takiego NIE chcecie przyzwać w ogniu walki.', 0),
(6234, 'plPL', 'Zdrada!', '', 0),
(6371, 'plPL', 'TO NIEMOŻLIWE!!', '', 0),
(7145, 'plPL', 'Lekcja się rozpoczęła!', '', 0),
(7172, 'plPL', 'Cisza! Nie widzisz, że mistrz mówi?', 'Cisza! Nie widzisz, że mistrz mówi?', 0),
(7173, 'plPL', 'Mniej grzechotania, więcej słuchania.', 'Mniej grzechotania, więcej słuchania.', 0),
(7174, 'plPL', 'Musimy się skupić, jeśli mamy wyhodować nasze smocze stado!', 'Musimy się skupić, jeśli mamy wyhodować nasze smocze stado!', 0),
(7175, 'plPL', 'Cisza! Nie mogę przegapić ani chwili tego wykładu!', 'Cisza! Nie mogę przegapić ani chwili tego wykładu!', 0),
